cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');

// Find orders for this user
const orders = db.prepare(\"SELECT * FROM orders WHERE customer_id = 'sofia_ramirez_629'\").all();
console.log('=== ORDERS ===');
console.log(JSON.stringify(orders, null, 2));

// Check if any order matches ORD-E0E671
const specific = db.prepare(\"SELECT * FROM orders WHERE order_id LIKE '%E0E671%'\").all();
console.log('\n=== ORDER matching E0E671 ===');
console.log(JSON.stringify(specific, null, 2));

db.close();
"

cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');

// Get order items for ORD-E0E671
const items = db.prepare(\"SELECT * FROM order_items WHERE order_id = 'ORD-E0E671'\").all();
console.log('=== ORDER ITEMS ===');
console.log(JSON.stringify(items, null, 2));

// Search for 'Aurora' product
const products = db.prepare(\"SELECT * FROM products WHERE name LIKE '%Aurora%'\").all();
console.log('\n=== AURORA PRODUCTS ===');
