// Search for 'Anker' or 'speaker' product
const speakers = db.prepare(\"SELECT * FROM products WHERE name LIKE '%Anker%' OR name LIKE '%speaker%' OR name LIKE '%Speaker%'\").all();
console.log('\n=== SPEAKER PRODUCTS ===');
console.log(JSON.stringify(speakers, null, 2));

db.close();
"

cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');
// Check order status and item details
const order = db.prepare(\"SELECT * FROM orders WHERE order_id = 'ORD-E0E671'\").get();
console.log('Order status:', order.status);
console.log('Source skill:', order.source_skill);

// Check the order_items table schema and item_status column
const items = db.prepare(\"SELECT * FROM order_items WHERE order_id = 'ORD-E0E671'\").all();
console.log(JSON.stringify(items, null, 2));

// Check all tables
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table' ORDER BY name\").all();
console.log('\nAll tables:', tables.map(t => t.name));
"

cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');

// Check the product's return policy details
const product = db.prepare(\"SELECT * FROM products WHERE product_id = 'PROD-73FAB4'\").get();
console.log('Return window (days):', product.return_window_days);
console.log('Restocking fee %:', product.restocking_fee_pct);

// Check warranties table for this product/order
const warranties = db.prepare(\"SELECT * FROM warranties WHERE order_id = 'ORD-E0E671' OR product_id = 'PROD-73FAB4'\").all();
console.log('\nWarranties:', JSON.stringify(warranties, null, 2));

// Check order_payments for this order
const payments = db.prepare(\"SELECT * FROM order_payments WHERE order_id = 'ORD-E0E671'\").all();
console.log('\nPayments:', JSON.stringify(payments, null, 2));

// Check user payment methods
const user = db.prepare(\"SELECT payment_methods_json FROM users WHERE user_id = 'user_1d80ab67'\").get();
console.log('\nPayment methods:', user.payment_methods_json);

db.close();
"

cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');

// Update the order item to reflect the return
db.prepare(\`
  UPDATE order_items
  SET item_status = 'return_requested',
      return_reason = 'Prefer a portable speaker instead of a desk lamp',
      refund_amount = 88.00,
      refund_method = 'cc_21e6eed2'
  WHERE oi_id = 'ITEM-E5801A' AND order_id = 'ORD-E0E671'
\`).run();

// Verify the update
const item = db.prepare(\"SELECT * FROM order_items WHERE oi_id = 'ITEM-E5801A'\").get();
console.log('Updated item:');
console.log(JSON.stringify(item, null, 2));

db.close();
"
